Here's a simple expense tracker. Add what you spent, pick a category and a month, and set a budget to see how much is left. Nothing is saved when you close the chat, so note down your totals before you leave.

```page
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#f6f7f5;color:#1f2a24}
  h2{margin:0 0 10px;font-size:18px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
  input,select{padding:7px;border:1px solid #c9d1cb;border-radius:6px;font-size:14px}
  button{padding:7px 12px;border:0;border-radius:6px;background:#2f7d5b;color:#fff;font-size:14px;cursor:pointer}
  button.x{background:#fff;color:#b3402f;padding:2px 8px;border:1px solid #e3c6c1}
  .big{font-size:26px;font-weight:600}
  .muted{color:#6b756f;font-size:13px}
  .bar{height:8px;background:#e6ebe7;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar div{height:100%;background:#2f7d5b}
  .over{color:#b3402f;font-weight:600}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eef1ee;gap:8px}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <label>Month <input type="month" id="month" value="2026-10"></label>
    <label>Budget (₹) <input type="number" id="budget" value="30000" min="0" style="width:110px"></label>
  </div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="row">
    <input id="what" placeholder="What for?" style="flex:1;min-width:120px">
    <input type="number" id="amt" placeholder="Amount (₹)" min="0" style="width:110px">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input type="date" id="date" value="2026-10-27">
    <button id="add">Add</button>
  </div>
</div>

<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>Entries</b><div id="list" style="margin-top:6px"></div></div>

<script>
var items=[], nextId=1;
function $(i){return document.getElementById(i)}
function fmt(n){return '₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2})}
function nice(d){return new Date(d+'T00:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'})}

function render(){
  var m=$('month').value;
  var rows=items.filter(function(x){return x.date.slice(0,7)===m});
  var total=rows.reduce(function(s,x){return s+x.amt},0);
  var budget=Number($('budget').value)||0;
  $('total').textContent=fmt(total);
  var left=$('left');
  if(budget>0){
    if(total>budget){left.className='muted over';left.textContent='Over budget by '+fmt(total-budget)}
    else{left.className='muted';left.textContent=fmt(budget-total)+' left of '+fmt(budget)}
  } else {left.className='muted';left.textContent='Set a budget to see what is left'}

  var by={};
  rows.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var c=$('cats');c.innerHTML='';
  var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a]});
  if(!keys.length){c.innerHTML='<span class="muted">Nothing yet for this month.</span>'}
  keys.forEach(function(k){
    var pct=total?Math.round(by[k]*100/total):0;
    var d=document.createElement('div');
    var t=document.createElement('div');t.className='item';t.style.border='0';t.style.padding='0';
    t.innerHTML='<span></span><span></span>';
    t.children[0].textContent=k+' ('+pct+'%)';
    t.children[1].textContent=fmt(by[k]);
    var b=document.createElement('div');b.className='bar';
    var f=document.createElement('div');f.style.width=pct+'%';b.appendChild(f);
    d.appendChild(t);d.appendChild(b);c.appendChild(d);
  });

  var l=$('list');l.innerHTML='';
  if(!rows.length){l.innerHTML='<span class="muted">No entries.</span>'}
  rows.slice().sort(function(a,b){return a.date<b.date?1:-1}).forEach(function(x){
    var d=document.createElement('div');d.className='item';
    var left=document.createElement('div');
    var a=document.createElement('div');a.textContent=x.what;
    var s=document.createElement('div');s.className='muted';s.textContent=nice(x.date)+' · '+x.cat;
    left.appendChild(a);left.appendChild(s);
    var r=document.createElement('div');r.className='row';
    var p=document.createElement('b');p.textContent=fmt(x.amt);
    var del=document.createElement('button');del.className='x';del.textContent='Delete';
    del.onclick=function(){items=items.filter(function(i){return i.id!==x.id});render()};
    r.appendChild(p);r.appendChild(del);
    d.appendChild(left);d.appendChild(r);l.appendChild(d);
  });
}

$('add').onclick=function(){
  var amt=Number($('amt').value);
  if(!amt||amt<=0||!$('date').value){return}
  items.push({id:nextId++,what:$('what').value.trim()||'Expense',amt:amt,cat:$('cat').value,date:$('date').value});
  $('what').value='';$('amt').value='';
  $('month').value=$('date').value.slice(0,7);
  render();
};
$('month').onchange=render;
$('budget').oninput=render;
render();
</script>
</body>
</html>
```

